```java
// ─── File: src/test/java/com/bank/binding/BindingTest.java ───
package com.bank.binding;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class BindingTest {

    Account ref = new SavingsAccount();  // reference: Account. Actual: SavingsAccount.

    // ═══ DYNAMIC BINDING: overridden instance method → actual type wins ═══
    @Test
    void dynamic_overriddenMethodUsesActualType() {
        assertThat(ref.getDescription()).isEqualTo("Savings Account");
        // ref is Account. Actual is SavingsAccount. JVM dispatches to SavingsAccount.
        // RUNTIME decision — dynamic binding via vtable!
    }

    // ═══ STATIC BINDING: static method → reference type wins ═══
    @Test
    void static_staticMethodUsesReferenceType() {
        assertThat(ref.getPolicy()).isEqualTo("Standard");
        // ref is Account → Account.getPolicy() → "Standard"
        // NOT "Savings Policy"! Static = compile-time binding to reference type.
    }

    @Test
    void static_changeReferenceChangesStaticResult() {
        SavingsAccount saRef = new SavingsAccount();
        assertThat(saRef.getPolicy()).isEqualTo("Savings Policy");
        // Change reference type → different static method called!
    }

    // ═══ STATIC BINDING: final method → cannot be overridden ═══
    @Test
    void static_finalMethodCannotBeOverridden() {
        assertThat(ref.getId()).isEqualTo("ACC-BASE");
        // final → compiled directly to Account.getId(). No vtable lookup.
    }

    // ═══ STATIC BINDING: private method → not inherited ═══
    @Test
    void static_privateMethodNotInherited() {
        assertThat(ref.callAudit()).contains("Account.audit");
        // audit() is private → not in vtable → static binding → Account.audit()
    }

    // ═══ WHY Parent p = new Child(); p.method() calls Child ═══
    @Test
    void why_parentRefCallsChildMethod() {
        Account parent = new SavingsAccount();
        // parent.getDescription() → compiler: "Account has getDescription? YES."
        // Bytecode: invokevirtual Account.getDescription()
        // Runtime: JVM looks at actual object → SavingsAccount
        // → SavingsAccount's vtable → SavingsAccount.getDescription()
        // → "Savings Account" ← CHILD'S VERSION!
        assertThat(parent.getDescription()).isEqualTo("Savings Account");
        // This is DYNAMIC BINDING — the foundation of runtime polymorphism!
    }
}
```
